#include "ling_torch_ops.hpp"
#include <torch/torch.h>
#include <cmath>
#include <limits>
#include <stdexcept>
#include <string>

namespace strata::ling_torch {
namespace {
void finite(const std::vector<float> &v, const char *what) {
  for (float x : v) if (!std::isfinite(x)) throw std::invalid_argument(std::string("nonfinite ") + what);
}
torch::Tensor input(const std::vector<float> &v, c10::Device d) {
  auto o=torch::TensorOptions().dtype(torch::kFloat32);
  return torch::from_blob(const_cast<float*>(v.data()),{static_cast<long>(v.size())},o).clone().to(d);
}
std::vector<float> host(const torch::Tensor &v, std::size_t n, const char *what) {
  auto h=v.to(torch::kCPU).contiguous().view({static_cast<long>(n)}); auto a=h.accessor<float,1>();
  std::vector<float> out(n); for(std::size_t i=0;i<n;++i) { out[i]=a[static_cast<long>(i)]; if(!std::isfinite(out[i])) throw std::runtime_error(std::string("nonfinite ")+what); } return out;
}
}
struct Ops::Impl { c10::Device device; explicit Impl(const char *name):device(c10::kCPU) { if(!name) throw std::invalid_argument("Ling Torch device is null"); std::string s(name); if(s=="cuda") device=c10::kCUDA; else if(s!="cpu") throw std::invalid_argument("Ling Torch device must be cpu or cuda"); } };
Ops::Ops(const char *d):impl_(std::make_unique<Impl>(d)) {} Ops::~Ops()=default;
bool Ops::sigmoid(const std::vector<float>&x,std::vector<float>&out,std::string&e) const { out.clear(); try { if(x.empty()) throw std::invalid_argument("Ling Torch sigmoid input is empty"); finite(x,"Ling Torch sigmoid input"); out=host(torch::sigmoid(input(x,impl_->device)),x.size(),"Ling Torch sigmoid output"); return true; } catch(const std::exception&z){e=z.what();return false;} }
bool Ops::rms_norm(const std::vector<float>&x,const std::vector<float>&w,std::vector<float>&out,std::string&e) const { out.clear(); try { if(x.empty()||x.size()!=w.size()) throw std::invalid_argument("Ling Torch RMS geometry"); finite(x,"Ling Torch RMS input");finite(w,"Ling Torch RMS weight"); auto a=input(x,impl_->device); auto gamma=input(w,impl_->device); auto inv=torch::rsqrt(a.pow(2).mean()+1e-6f); out=host(gamma*(inv*a),x.size(),"Ling Torch RMS output"); return true; } catch(const std::exception&z){e=z.what();return false;} }
bool Ops::swiglu(const std::vector<float>&g,const std::vector<float>&u,std::vector<float>&out,std::string&e) const { out.clear(); try { if(g.empty()||g.size()!=u.size()) throw std::invalid_argument("Ling Torch SwiGLU geometry"); finite(g,"Ling Torch SwiGLU gate"); finite(u,"Ling Torch SwiGLU up"); out=host(torch::silu(input(g,impl_->device))*input(u,impl_->device),g.size(),"Ling Torch SwiGLU output"); return true; } catch(const std::exception&z){e=z.what();return false;} }
bool Ops::kda_output_norm_gate(const std::vector<float>&x,const std::vector<float>&w,const std::vector<float>&g,std::size_t heads,std::size_t width,std::vector<float>&out,std::string&e) const { out.clear(); try { if(!heads||!width||heads>std::numeric_limits<std::size_t>::max()/width||x.size()!=heads*width||g.size()!=x.size()||w.size()!=width) throw std::invalid_argument("Ling Torch KDA output normalization geometry"); finite(x,"Ling Torch KDA input");finite(w,"Ling Torch KDA weight");finite(g,"Ling Torch KDA gate"); auto a=input(x,impl_->device).view({static_cast<long>(heads),static_cast<long>(width)});auto gamma=input(w,impl_->device).view({1,static_cast<long>(width)});auto gate=input(g,impl_->device).view({static_cast<long>(heads),static_cast<long>(width)}); auto inv=torch::rsqrt(a.pow(2).mean(-1,true)+1e-6f); out=host((a*inv*gamma)*torch::sigmoid(gate),x.size(),"Ling Torch KDA output"); return true; } catch(const std::exception&z){e=z.what();return false;} }
bool Ops::weighted_sum(const std::vector<std::vector<float>>&rows,const std::vector<float>&weights,std::vector<float>&out,std::string&e) const { out.clear(); try { if(rows.empty()||rows.size()!=weights.size()||rows.front().empty()) throw std::invalid_argument("Ling Torch weighted sum geometry"); const auto width=rows.front().size(); if(rows.size()>std::numeric_limits<std::size_t>::max()/width) throw std::invalid_argument("Ling Torch weighted sum overflow"); std::vector<float> flat;flat.reserve(rows.size()*width);for(const auto&r:rows){if(r.size()!=width)throw std::invalid_argument("Ling Torch weighted sum row geometry");finite(r,"Ling Torch weighted row");flat.insert(flat.end(),r.begin(),r.end());}finite(weights,"Ling Torch weights");auto m=input(flat,impl_->device).view({1,static_cast<long>(rows.size()),static_cast<long>(width)});auto s=input(weights,impl_->device).view({1,static_cast<long>(rows.size()),1});out=host((m*s).sum(1),width,"Ling Torch weighted sum output");return true;}catch(const std::exception&z){e=z.what();return false;} }
bool Ops::route(const std::vector<float>&logits,const std::vector<float>&bias,std::vector<std::size_t>&ids,std::vector<float>&weights,std::vector<float>&scores,std::vector<float>&corrected,std::string&e) const { ids.clear();weights.clear();scores.clear();corrected.clear();try { if(logits.size()!=128||bias.size()!=128) throw std::invalid_argument("Ling Torch router geometry");finite(logits,"Ling Torch router logits");finite(bias,"Ling Torch router bias");auto l=input(logits,impl_->device).view({1,128});auto b=input(bias,impl_->device).view({1,128});auto sc=torch::sigmoid(l),routed=sc+b;auto grouped=routed.view({1,8,16});auto group_scores=std::get<0>(torch::topk(grouped,2,-1,true,true)).sum(-1);auto selected_groups=std::get<1>(torch::topk(group_scores,4,-1,true,false));auto mask=torch::zeros_like(group_scores);mask.scatter_(1,selected_groups,1);auto expanded=mask.unsqueeze(-1).expand({1,8,16}).reshape({1,128});auto filtered=torch::where(expanded.to(torch::kBool),routed,torch::full_like(routed,-std::numeric_limits<float>::infinity()));auto top=torch::topk(filtered,8,1,true,true);auto ti=std::get<1>(top);auto tw=torch::gather(sc,1,ti);tw=tw/(tw.sum(-1,true)+1e-20f);tw*=2.5f;auto sh=sc.to(torch::kCPU).contiguous();auto rh=routed.to(torch::kCPU).contiguous();auto ih=ti.to(torch::kCPU).contiguous();auto wh=tw.to(torch::kCPU).contiguous();auto sa=sh.accessor<float,2>();auto ra=rh.accessor<float,2>();auto ia=ih.accessor<int64_t,2>();auto wa=wh.accessor<float,2>();scores.resize(128);corrected.resize(128);ids.resize(8);weights.resize(8);for(int i=0;i<128;++i){scores[i]=sa[0][i];corrected[i]=ra[0][i];}for(int i=0;i<8;++i){if(ia[0][i]<0||ia[0][i]>=128)throw std::runtime_error("Ling Torch router index");ids[i]=static_cast<std::size_t>(ia[0][i]);weights[i]=wa[0][i];}return true;}catch(const std::exception&z){e=z.what();return false;} }
} // namespace strata::ling_torch
